#!/usr/bin/env python3
# Route 22 optional early rival battle: rival_battle + walk_npc verbs,
# ROUTE_22 ambush map script, findNpc/setObjectHidden reveal-by-name.
# Ported from story5.lua M.ROUTE_22 + route22Scene + Commands.lua.
# Build-only (no re-cook) -- requires patch_cook_route22 already deployed.
import base64, json, os, sys
ROOT = os.path.expanduser("~/pocket-voxel")
if not os.path.isdir(os.path.join(ROOT, "voxelmon")):
    ROOT = os.getcwd()
DATA = json.loads(base64.b64decode(""))
hunks = DATA["hunks"]; sentinels = DATA["sentinels"]
for rel, marker in sentinels.items():
    p = os.path.join(ROOT, rel)
    if os.path.isfile(p) and marker in open(p, encoding="utf-8").read():
        sys.exit("ABORT: '{}' already present in {} -- already applied.".format(marker, rel))
files = {}
for h in hunks:
    p = os.path.join(ROOT, h["path"])
    if p not in files:
        if not os.path.isfile(p): sys.exit("ABORT: missing " + h["path"])
        files[p] = open(p, encoding="utf-8").read()
    old = base64.b64decode(h["old"]).decode()
    if files[p].count(old) != 1:
        sys.exit("ABORT: anchor in {} not unique (need prior patches applied) -- nothing written.".format(h["path"]))
for h in hunks:
    p = os.path.join(ROOT, h["path"])
    files[p] = files[p].replace(base64.b64decode(h["old"]).decode(), base64.b64decode(h["new"]).decode(), 1)
conf = {}
for p, text in files.items():
    open(p, "w", encoding="utf-8").write(text)
    conf[os.path.relpath(p, ROOT)] = {"bytes": len(text)}
print("PATCHED (root=" + ROOT + "):")
print(json.dumps(conf, indent=2))
print("verbs +2: rival_battle walk_npc | ROUTE_22.onStep ambush | reveal-by-name")
